code.en:
# a full training loop: gradient descent fits w toward 2 (y = 2x)
w = 0.0
for _ in range(200):
    for x, y in zip([1, 2, 3], [2, 4, 6]):
        w -= 0.01 * 2 * (w * x - y) * x
print(round(w, 2))

